        try:
            val = getattr(data, attr)
            if not callable(val):
                if hasattr(val, 'shape'):
                    print(f'  {attr}: shape={val.shape}, dtype={val.dtype}')
                elif isinstance(val, (int, float, str, bool)):
                    print(f'  {attr}: {val}')
        except:
            pass
